with ins as (insert into public.artist_eras (artist_slug,from_year,to_year,sound,tags,source_url,source_name,palette) select x.s,x.f,x.t,x.snd,array(select json_array_elements_text(x.tags)),x.u,x.n,x.p from json_to_recordset('[{"s":"prismer","f":2018,"t":2019,"snd":"Dark drum and bass and jungle sets","tags":["drum and bass","jungle","liquid drum and bass"],"u":"https://www.thewildcity.com/mixes/6930-wild-city-148-rohan-kal","n":"Wild City","p":"blush"},{"s":"prismer","f":2020,"t":null,"snd":"Thumping bass, breaks and techno","tags":["bass","breaks","techno","electro"],"u":"https://www.youtube.com/watch?v=28cFJOVcjc8","n":"BOXOUT FM (YouTube)","p":"ink"},{"s":"dj-pants","f":2024,"t":null,"snd":"Balearic-tinged new-age electronica and bass-heavy house","tags":["Balearic","house","breaks","new-age"],"u":"https://www.thewildcity.com/mixes/20911-wild-city-242-dj-pants","n":"Wild City","p":"night"},{"s":"electroson","f":2026,"t":null,"snd":"Cerebral, relentless and exploratory techno selections","tags":["techno","experimental"],"u":"https://ra.co/events/2484477","n":"Resident Advisor","p":"ink"},{"s":"spiralynk","f":2019,"t":2024,"snd":"Organised chaos across IDM, ambient, glitch, drone and noise","tags":["IDM","ambient","glitch","drone","noise"],"u":"https://www.mixcloud.com/aubele/techno-quarantuned-feat-spiralynk-episode-5/","n":"Aubele (Mixcloud)","p":"night"},{"s":"spiralynk","f":2025,"t":null,"snd":"Angular, liquid leftfield bass and drum and bass","tags":["idm","drum and bass","leftfield bass","elektron"],"u":"https://antarikshrecords.bandcamp.com/album/liminal-rift-ep","n":"Antariksh Records (Bandcamp)","p":"blush"},{"s":"mogasu","f":2018,"t":2024,"snd":"Flavourful disco and house mixes","tags":["disco","house"],"u":"https://soundcloud.com/mogasu/disco-on-a-wednesday","n":"SoundCloud (Mogasu)","p":"night"},{"s":"mogasu","f":2025,"t":null,"snd":"Deep house, minimal house and leftfield electronica","tags":["deep house","minimal house","leftfield electronica"],"u":"https://www.youtube.com/watch?v=WGpxE82dKkc","n":"Piknik (YouTube)","p":"blush"},{"s":"bawra","f":2026,"t":null,"snd":"Understated, hypnotic minimal techno with morphing melodies","tags":["techno","acid techno","minimal techno"],"u":"https://www.mixcloud.com/WildCity/wild-city-264-baawra/","n":"Wild City","p":"ink"},{"s":"thegreybox","f":2019,"t":null,"snd":"Hip-hop, soul, trap and house, classic and edgy","tags":["hip-hop","soul","trap","house"],"u":"https://www.thewildcity.com/features/15842-a-comprehensive-guide-to-the-music-at-magnetic-fields-2019","n":"Wild City","p":"blush"}]'::json) as x(s text,f int,t int,snd text,tags json,u text,n text,p text) join public.artists a on a.slug=x.s where not exists (select 1 from public.artist_eras e where e.artist_slug=x.s and e.from_year=x.f) returning 1) select count(*) from ins;